// generated by gemini-3.5-flash-lite for PR #6020 (round 0): cbor_large_vector_output
// intent: Verify that generating CBOR binary output for a large array of numbers (exceeding the window size) produces valid output bytes correctly.
#include <nlohmann/json.hpp>
#include <iostream>
#include <vector>

int main() {
    try {
        nlohmann::json j = nlohmann::json::array();
        for (int i = 0; i < 20000; ++i) {
            j.push_back(i);
        }
        std::vector<uint8_t> v = nlohmann::json::to_cbor(j);
        std::cout << "CBOR size: " << v.size() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << "\n";
    }
    return 0;
}
